from .base_cl_tool import BaseClToolInterface


class LicenceToolInterface(BaseClToolInterface):
    """ Keywords for licence tool related commands."""

    def query_licence(self, timeout='15min', **kwargs):
        """
        Gets BTS Licence XML file from given site.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['querylicence']
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='queryLicence', params=params,
                                               trs_ip=ne, flags=flags)

    def upload_licence(self, filename, file_dir, timeout='15min', **kwargs):
        """
        Uploads licence to specified path or directory.

        :param  str  filename: Filename of licence file to be uploaded to BTS.
        :param  str  file_dir: Directory/path where the licence file is located.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'filename': filename, 'filedir': file_dir, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='uploadLicence', params=params,
                                               trs_ip=ne, flags=flags)

    def delete_licence(self, filename, timeout='15min', **kwargs):
        """
        Deletes licence from specified path or directory.

        :param  str  filename:     Filename of licence file to be deleted in BTS.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'filename': filename, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='deleteLicence', params=params,
                                               trs_ip=ne, flags=flags)
